mapper.select:
SELECT R.INSTITUTION_ID, R.REQ_SEQ, R.STATUS_CD, R.CLOSED_AT, R.CLOSE_REASON FROM PLAN_COLLECT_REQ R
 WHERE R.OPEN_INST_ID IS NULL AND R.CLOSED_AT >= #{since}
 ORDER BY R.INSTITUTION_ID, R.REQ_SEQ DESC

mapper.update:
UPDATE PLAN_COLLECT_REQ
   SET STATUS_CD = #{to}, OPEN_INST_ID = NULL, CLOSED_AT = #{at}, CLOSED_BY = #{empNo,jdbcType=VARCHAR},
       CLOSE_REASON = #{reason,jdbcType=VARCHAR}
 WHERE REQ_KEY = #{reqKey}
   AND STATUS_CD IN #{s}
